components.css:
.ds-verification-dialog{width:min(100% - 32px,520px);max-height:calc(100dvh - 32px);margin:auto;padding:0;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);overflow-y:auto;font-family:var(--font-manrope),sans-serif}
.ds-verification-dialog::backdrop{background:#071a13b8}
.ds-verification-content{padding:28px;display:grid;gap:20px}
.ds-verification-content h2{font-size:24px;line-height:1.25;margin:0;letter-spacing:-.02em}
.ds-verification-content p{font-size:16px;line-height:1.55;margin:0;color:var(--muted)}
.ds-verification-content form{display:grid;gap:18px}
.ds-verification-content label{display:grid;gap:8px;font-size:14px;font-weight:700}
.ds-verification-content input,.ds-verification-content select{width:100%;min-width:0;font-size:16px}
.ds-verification-content input[name=code]{font-variant-numeric:tabular-nums;letter-spacing:.2em;font-size:24px}
.ds-verification-target{display:grid;gap:6px;padding:16px;background:var(--mint);border-radius:7px;overflow-wrap:anywhere}
.ds-verification-target strong{font-size:14px;color:var(--muted)}
.ds-verification-target span{font-size:18px;font-weight:700}
.ds-verification-setup{display:grid;gap:16px;justify-items:start}
.ds-verification-setup label{width:100%;min-width:0}
.ds-verification-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}
.ds-verification-footer .ds-small-link{font-size:14px;text-align:left}
.ds-verification-content .ds-button{min-height:46px}
@media(max-width:760px){.ds-verification-dialog{width:100%;max-width:none;max-height:calc(100dvh - 16px);margin:auto 0 0;border-radius:12px 12px 0 0}.ds-verification-content{padding:24px 20px max(24px,env(safe-area-inset-bottom))}.ds-verification-footer{align-items:stretch;flex-direction:column}.ds-verification-footer .ds-button{width:100%}} .ds-verification-dialog input,.ds-verification-dialog select{font-family:var(--font-manrope),sans-serif;padding:12px 14px;border:1px solid var(--line);border-radius:7px;background:var(--surface);color:var(--ink)}.ds-button{font-family:var(--font-manrope),sans-serif;font-size:15px;font-weight:700;min-height:46px;line-height:1.35;padding:13px 22px;border-radius:7px;border:1px solid transparent;cursor:pointer;transition:background .2s,color .2s,transform .3s cubic-bezier(.16,1,.3,1)}.ds-primary{background:var(--action);color:var(--action-ink)}.ds-primary:hover{filter:brightness(.93);transform:translateY(-1px)}.ds-secondary{background:var(--surface);color:var(--ink);border-color:var(--line)}.ds-secondary:hover{background:var(--mint)}.ds-verification-dialog :is(button,input,select):focus-visible{outline:3px solid var(--action);outline-offset:4px}.ds-button:disabled{opacity:.55;cursor:not-allowed}@media(prefers-reduced-motion:reduce){.ds-button{transition:none}}
